package com.householdfinance.finance.domain;import java.time.*;import java.util.UUID;public final class HouseholdBill{private final BillId id=BillId.newId();private final HouseholdId householdId;private final String name;private final Money amount;private final LocalDate dueDate;private BillStatus status=BillStatus.ACTIVE;private HouseholdBill(HouseholdId h,String n,Money a,LocalDate d){if(!a.isPositive())throw new DomainException("Bill amount must be positive");householdId=h;name=n;amount=a;dueDate=d;}public static HouseholdBill create(HouseholdId h,String n,Money a,LocalDate d){return new HouseholdBill(h,n,a,d);}public static HouseholdBill rehydrate(UUID id,HouseholdId h,String n,Money amount,LocalDate dueDate,BillStatus status){var bill=new HouseholdBill(h,n,amount,dueDate);bill.status=status;return bill;}public BillId id(){return id;}public HouseholdId householdId(){return householdId;}public String name(){return name;}public Money amount(){return amount;}public LocalDate dueDate(){return dueDate;}public BillStatus status(){return status;}}
